function build(failShipping: boolean) {
  const ledger: string[] = [];
  const app = createTestApp({ flows: [OrderIntakeFlow] });
  for (const toolId of OrderIntakeTools) {
    const label = toolId.slice("order-intake-".length);
    app.effectRuntime.register(
      toolId,
      new ToolEffect(async () => {
        if (label === "ship" && failShipping) throw new Error("carrier unavailable");
        ledger.push(label);
        return {};
      })
    );
